if(arr.length<=1) return [arr];
let res=[];
for(let i=0;i<arr.length;i++){
const rest = arr.slice(0,i).concat(arr.slice(i+1));
for(const p of permute(rest)) res.push([arr[i],...p]);
}
return res;
}
